def format_bytes(n):
    if n < 1024:
        return f"{n/1024:.1f} B"
    elif n < 1024**2:
        return f"{n/(1024**2):.1f} KB"
    elif n < 1024**3:
        return f"{n/(1024**3):.1f} MB"
    elif n < 1024**4:
        return f"{n/(1024**4):.1f} GB"
    else:
        return f"{n/(1024**5):.1f} TB"
